/**
 * Lightweight Standalone JSZip implementation for browser extension (STORE uncompressed mode).
 * Works offline with 100% compatibility across Windows, Mac, Linux, and web archivers.
 */
class JSZip {
  constructor() {
    this.files = {};
  }

  file(name, data) {
    // data can be String, ArrayBuffer, Uint8Array, or Blob
    this.files[name] = data;
    return this;
  }

  async generateAsync(options = { type: 'blob' }) {
    const fileEntries = [];
    let currentOffset = 0;

    for (const filename of Object.keys(this.files)) {
      const rawData = this.files[filename];
      let bytes;

      if (rawData instanceof Uint8Array) {
        bytes = rawData;
      } else if (rawData instanceof ArrayBuffer) {
        bytes = new Uint8Array(rawData);
      } else if (typeof rawData === 'string') {
        bytes = new TextEncoder().encode(rawData);
      } else if (rawData instanceof Blob) {
        bytes = new Uint8Array(await rawData.arrayBuffer());
      } else {
        bytes = new Uint8Array();
      }

      const encodedFilename = new TextEncoder().encode(filename);
      const crc = JSZip.crc32(bytes);
      const size = bytes.length;

      // Local file header (30 bytes + filename length)
      const localHeader = new Uint8Array(30 + encodedFilename.length);
      const view = new DataView(localHeader.buffer);

      view.setUint32(0, 0x04034b50, true); // Local file header signature
      view.setUint16(4, 20, true);         // Version needed to extract
      view.setUint16(6, 0, true);          // General purpose bit flag
      view.setUint16(8, 0, true);          // Compression method (0 = STORE)
      view.setUint16(10, 0, true);         // File last modification time
      view.setUint16(12, 0, true);         // File last modification date
      view.setUint32(14, crc, true);       // CRC-32
      view.setUint32(18, size, true);      // Compressed size
      view.setUint32(22, size, true);      // Uncompressed size
      view.setUint16(26, encodedFilename.length, true); // Filename length
      view.setUint16(28, 0, true);         // Extra field length

      localHeader.set(encodedFilename, 30);

      fileEntries.push({
        name: filename,
        encodedName: encodedFilename,
        localHeader,
        data: bytes,
        crc,
        size,
        offset: currentOffset
      });

      currentOffset += localHeader.length + size;
    }

    // Build Central Directory
    const centralDirectoryParts = [];
    let cdSize = 0;

    for (const entry of fileEntries) {
      const cdHeader = new Uint8Array(46 + entry.encodedName.length);
      const view = new DataView(cdHeader.buffer);

      view.setUint32(0, 0x02014b50, true); // Central directory file header signature
      view.setUint16(4, 20, true);         // Version made by
      view.setUint16(6, 20, true);         // Version needed to extract
      view.setUint16(8, 0, true);          // General purpose bit flag
      view.setUint16(10, 0, true);         // Compression method (0 = STORE)
      view.setUint16(12, 0, true);         // File last modification time
      view.setUint16(14, 0, true);         // File last modification date
      view.setUint32(16, entry.crc, true); // CRC-32
      view.setUint32(20, entry.size, true);// Compressed size
      view.setUint32(24, entry.size, true);// Uncompressed size
      view.setUint16(28, entry.encodedName.length, true); // Filename length
      view.setUint16(30, 0, true);         // Extra field length
      view.setUint16(32, 0, true);         // File comment length
      view.setUint16(34, 0, true);         // Disk number start
      view.setUint16(36, 0, true);         // Internal file attributes
      view.setUint32(38, 0, true);         // External file attributes
      view.setUint32(42, entry.offset, true); // Relative offset of local header

      cdHeader.set(entry.encodedName, 46);
      centralDirectoryParts.push(cdHeader);
      cdSize += cdHeader.length;
    }

    // End of Central Directory Record (22 bytes)
    const eocd = new Uint8Array(22);
    const eocdView = new DataView(eocd.buffer);

    eocdView.setUint32(0, 0x06054b50, true); // EOCD signature
    eocdView.setUint16(4, 0, true);          // Number of this disk
    eocdView.setUint16(6, 0, true);          // Disk where central directory starts
    eocdView.setUint16(8, fileEntries.length, true); // Number of central directory records on this disk
    eocdView.setUint16(10, fileEntries.length, true); // Total number of central directory records
    eocdView.setUint32(12, cdSize, true);    // Size of central directory
    eocdView.setUint32(16, currentOffset, true); // Offset of start of central directory
    eocdView.setUint16(20, 0, true);         // ZIP file comment length

    // Assemble final ZIP buffer
    const chunks = [];
    for (const entry of fileEntries) {
      chunks.push(entry.localHeader);
      chunks.push(entry.data);
    }
    for (const cdHeader of centralDirectoryParts) {
      chunks.push(cdHeader);
    }
    chunks.push(eocd);

    const totalLen = chunks.reduce((sum, c) => sum + c.length, 0);
    const finalBuffer = new Uint8Array(totalLen);
    let offset = 0;
    for (const chunk of chunks) {
      finalBuffer.set(chunk, offset);
      offset += chunk.length;
    }

    if (options.type === 'blob') {
      return new Blob([finalBuffer], { type: 'application/zip' });
    }
    return finalBuffer;
  }

  static crc32(buf) {
    let c = 0xffffffff;
    for (let i = 0; i < buf.length; i++) {
      c ^= buf[i];
      for (let k = 0; k < 8; k++) {
        c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
      }
    }
    return (c ^ 0xffffffff) >>> 0;
  }
}

if (typeof window !== 'undefined') {
  window.JSZip = JSZip;
}
